python3 -c $'import itertools as it,json,sys\nP=it.product\nC=lambda v:v or sys.exit(\'FAIL\')\nM=lambda d,p,r:(d,set(p),set(r))\nA=[M((0,1),(0,),((0,1),)),M((0,1,2),(0,2),((0,1),(1,1),(2,1))),M((0,),(0,),((0,0),)),M((0,1),(1,),((1,0),)),M((0,1),(),())]\na=(\'P\',0);b=(\'R\',0,1);e=(\'=\',0,1);z=(\'&\',a,b)\nT=[a,b,e,z,(\'|\',a,b),(\'E\',0,b),(\'E\',1,z),(\'E\',0,(\'E\',1,z)),(\'|\',(\'E\',0,b),e)]\nW=T+[(\'!\',a),(\'!\',e),(\'A\',1,(\'|\',a,b)),(\'!\',(\'E\',0,z)),(\'A\',0,(\'E\',1,b))]\ndef V(t,m,s):\n o=t[0]\n if o in \'PCLR\':return (s[t[1]] if o in \'PC\' else (s[t[1]],s[t[2]])) in m[1 if o in \'PC\' else 2]\n if o==\'=\':return s[t[1]]==s[t[2]]\n if o==\'!\':return not V(t[1],m,s)\n if o in \'&|\':return (V(t[1],m,s) and V(t[2],m,s)) if o==\'&\' else (V(t[1],m,s) or V(t[2],m,s))\n i=t[1]\n v=[V(t[2],m,s[:i]+(k,)+s[i+1:]) for k in m[0]]\n return any(v) if o==\'E\' else all(v)\ndef Q(t):return ({\'P\':\'C\',\'R\':\'L\'}.get(t[0],t[0]),*(Q(x) if isinstance(x,tuple) else x for x in t[1:]))\nH=J=I=K=0\nfor m in A:\n for n in A:\n  for q in P(n[0],repeat=len(m[0])):\n   f=dict(zip(m[0],q))\n   if not (all(f[x] in n[1] for x in m[1]) and all((f[x],f[y]) in n[2] for x,y in m[2])):continue\n   H+=1\n   iso=len(q)==len(set(q))==len(n[0]) and all((x in m[1])==(f[x] in n[1]) for x in m[0]) and all(((x,y) in m[2])==((f[x],f[y]) in n[2]) for x in m[0] for y in m[0])\n   I+=iso\n   for s in P(m[0],repeat=2):\n    u=tuple(f[x] for x in s)\n    for t in T:\n     C(not V(t,m,s) or V(Q(t),n,u))\n     J+=1\n    if iso:\n     for t in W:\n      C(V(t,m,s)==V(Q(t),n,u))\n      K+=1\nC(V((\'!\',a),A[0],(1,0)) and not V((\'!\',Q(a)),A[2],(0,0)))\nC(V(a,A[0],(0,0)) and not V(Q(a),A[4],(0,0)))\nprint(json.dumps(dict(version=\'G7\',finite_models=len(A),homomorphisms=H,positive_preservation_tests=J,isomorphisms=I,full_truth_equivalences=K,not_counterexample=\'A:x=1 -> C:x=0\',arbitrary_rename_counterexample=True,all_domains_proved=False,God_identity_proved=False),sort_keys=True))' "$@"
